rep("  let x = `<div class=\"at-d\"><h5>CE QUE LA DIAPO DÉCLARE</h5><div class=\"l\">${a ? '<b>Activité ' + a.num + '</b> — ' + esc(a.titre) + ' · diapo ' + rang + ' sur ' + dA.length + ' de l\\'activité' : (e.role === 'fin' ? '<b>Cahier de textes</b> — les cinq minutes réservées' : '<i>hors activité</i>')}</div><div class=\"l\">Heure prévue : <b>H${e.heure}</b>${sim ? ' (' + esc(sim.jour.replace(/ 2026$/, '')) + ')' : ''} · <b>${e.role === 'fin' ? 5 : (e.dur || 0)} min</b> · ${hhmm(cr.debut)} → ${hhmm(cr.fin)} — <span class=\"at-note\">proposée d'après les durées ; déplaçable</span></div><div class=\"l\">Notions travaillées : ${comp.length ? comp.map(n => '<b>' + esc(n) + '</b>').join(', ') : '<i>aucune</i>'}</div><div class=\"l\">Remobilise : ${remob.length ? remob.map(n => '<b>' + esc(n) + '</b>').join(', ') : '<i>rien</i>'}</div><div class=\"l\">Éléments : ${nEl}${nEl > 1 ? ' · dévoilés un par un' : ''}</div></div>`;",
    r"""  const acts0 = DATA.activites[String(S.si)] || []; const heures = [...new Set(E.map(z => z.heure))].sort(); const chips = (ids, quoi) => ids.map(id => `<span class="chip" data-n="${esc(id)}" title="${esc(libNotion(id))}">${esc(libNotion(id))}<span class="x" data-retire="${quoi}" data-id="${esc(id)}" title="Retire cette notion">✕</span></span>`).join('');
  let x = e.role === 'fin' ? `<div class="at-d"><h5>CE QUE LA DIAPO DÉCLARE</h5><div class="l"><b>Fin d'heure</b> — posée par le site, les cinq minutes réservées au cahier ; pas de numéro d'activité ; ne se duplique pas, ne glisse pas, ne se retire pas (2.6)</div><div class="l">Heure : <b>H${e.heure}</b>${sim ? ' (' + esc(sim.jour.replace(/ 2026$/, '')) + ')' : ''} · 5 min</div></div>` : `<div class="at-d"><h5>CE QUE LA DIAPO DÉCLARE — tout s'écrit ici</h5><div class="l">Activité : <select id="dc-act" title="L'activité de cette diapo — une activité a un numéro continu sur le chapitre, un titre, une ou plusieurs diapos (3.2 bis)">${acts0.map(z => `<option value="${z.id}" ${a && a.id === z.id ? 'selected' : ''}>A${z.num} · ${esc(z.titre)}</option>`).join('')}<option value="" ${!a ? 'selected' : ''}>— hors activité (rituel)</option><option value="+">+ nouvelle activité…</option></select></div>${a ? `<div class="l">Titre de l'activité : <span class="ed" id="dc-atitre" contenteditable="plaintext-only" title="Le titre de l'activité, écrit ici">${esc(a.titre)}</span> <span class="at-note">· ${dA.length} diapo${dA.length > 1 ? 's' : ''} · diapo ${rang} sur ${dA.length}</span></div>` : ''}<div class="l">Diapo : <span class="ed" id="dc-titre" contenteditable="plaintext-only" title="Le titre de la diapo">${esc(e.act)}</span> · durée <input id="dc-dur" type="number" min="1" value="${e.dur || 0}" style="width:52px" title="Les minutes prévues : l'heure prévue de la suite se recalcule"> min · rôle : <select id="dc-role" title="réactivation : première de son heure · bilan : dernier de la séance, unique · fin d'heure : posée par le site"><option value="" ${!e.role ? 'selected' : ''}>aucun</option><option value="reactivation" ${e.role === 'reactivation' ? 'selected' : ''}>réactivation (première de son heure)</option><option value="bilan" ${e.role === 'bilan' ? 'selected' : ''}>bilan (dernier de la séance)</option><option value="fin" disabled>fin d'heure (posée par le site)</option></select></div><div class="l">Heure prévue : <b>H${e.heure}</b>${sim ? ' (' + esc(sim.jour.replace(/ 2026$/, '')) + ')' : ''} · ${hhmm(cr.debut)} → ${hhmm(cr.fin)} — <span class="at-note">proposée d'après les durées</span>${heures.includes(e.heure + 1) ? ` · <span class="plus" data-heure="${e.heure + 1}" title="Passe la diapo en H${e.heure + 1}, en tête de cette heure : le compte des deux heures se recalcule">↓ passer en H${e.heure + 1}</span>` : ''}${heures.includes(e.heure - 1) ? ` · <span class="plus" data-heure="${e.heure - 1}" title="Passe la diapo en H${e.heure - 1}, à la fin de cette heure (avant sa fin d'heure)">↑ passer en H${e.heure - 1}</span>` : ''}</div><div class="l">Notions travaillées : ${chips(e.comp || [], 'comp')} <span class="plus" data-plus="comp" title="Ajoute une notion travaillée par cette diapo">+ notion…</span></div><div class="l">Remobilise : ${chips(e.remob || [], 'remob')} <span class="plus" data-plus="remob" title="Ajoute une notion que cette diapo suppose acquise">+ notion…</span> · <span class="plus" data-proposer="1" title="Proposition par défaut : les notions de la même famille travaillées plus tôt dans le chapitre (2.7)">proposer</span></div><div class="l">Légende de surlignage : <span class="ed" id="dc-leg" contenteditable="plaintext-only" title="jaune = … · vert = … (facultatif)">${e.legende ? Object.keys(e.legende).map(k => k + ' = ' + e.legende[k]).join(' · ') : ''}</span>${e.legende ? '' : '<span class="at-note"> (facultatif)</span>'}</div><div class="l">Éléments : ${nEl}${nEl > 1 ? ' · dévoilés un par un' : ''}</div></div>`;
  /* le travail à faire prévu par heure (2.3) */ const tp = DATA.travailPrevu || (DATA.travailPrevu = {}); const cleTp = S.si + '|' + e.heure; const hSuiv = heures.filter(z => z > e.heure); x += `<div class="at-d"><h5>L'HEURE ${e.heure} — le travail à faire prévu (2.3)</h5><div class="l">Proposé au T-5 de cette heure, dans le cahier de textes : <span class="ed" id="dc-tp" contenteditable="plaintext-only" title="Le travail à faire que le T-5 proposera à la fin de cette heure ; ce que l'heure suivante remobilisera">${esc(tp[cleTp] || '')}</span>${tp[cleTp] ? '' : '<span class="at-note"> (rien de prévu)</span>'}</div><div class="l at-note">Le spiralaire : ce que l'heure suivante remobilisera.</div></div>`;
  /* les activités du chapitre (3.2 bis) */ const sansNum = E.map((z, i) => ({ z, i })).filter(o => !o.z.role && !actDe(o.z)); x += `<div class="at-d"><h5>LES ACTIVITÉS DU CHAPITRE</h5>${acts0.slice().sort((p1, p2) => p1.num - p2.num).map(z => { const d = diaposAct(z); const hs = [...new Set(d.map(i => E[i] && E[i].heure).filter(Boolean))]; return `<div class="act-l"><span class="n">A${z.num}</span><span>${esc(z.titre)}</span><span class="d">${d.length} diapo${d.length > 1 ? 's' : ''} · ${hs.map(h => 'H' + h).join(', ') || '—'}</span></div>`; }).join('')}${sansNum.map(o => `<div class="act-l sans"><span class="n">—</span><span>${esc(o.z.act)}</span><span class="d warn">sans numéro d'activité : refus à l'import (3.2 bis)</span></div>`).join('')}<div class="l"><span class="plus" data-nouvelle-act="1" title="Une activité de plus, numérotée à la suite">+ activité</span> · <span class="plus" data-renum="1" title="Renumérote toutes les activités dans l'ordre des diapos, sans trou">renuméroter (continu)</span></div></div>`;""")
