rep("function blocDe(el){", r"""/* ── (p5) la carte « Ce que la diapo déclare » qui s'écrit ── */
function nouvelleActivite(titre){ const acts = DATA.activites[String(S.si)] = DATA.activites[String(S.si)] || []; const num = acts.reduce((m, z) => Math.max(m, parseInt(z.num) || 0), 0) + 1; const a = { id: 'a' + S.si + '-n' + Date.now().toString(36), num, titre: titre || 'Activité ' + num, diapos: [] }; acts.push(a); journal('atelier-activite', { id: a.id, num }); return a; }
function renumeroter(){ const E = seance().ecrans; const acts = DATA.activites[String(S.si)] || []; let n = 0; const vus = new Set(); E.forEach(e => { const a = actDe(e); if (a && !vus.has(a.id)) { vus.add(a.id); a.num = ++n; } }); acts.filter(a => !vus.has(a.id)).forEach(a => { a.num = ++n; }); marquerModif({ renumerote: n }); tout(); }
function choixNotion(cb){ fermerChoix(); const E = seance().ecrans; const z = document.createElement('div'); z.className = 'choix-obj'; const vues = {}; const chap = [...new Set(E.flatMap(e => (e.comp || []).concat(e.remob || [])))]; chap.forEach(id => { vues[id] = 1; }); z.innerHTML = `<h4><span>QUELLE NOTION ? — celles du chapitre d'abord, puis tout le programme par famille</span><span class="x">✕</span></h4><div class="form"><div class="fe">${chap.map(id => `<span class="fi" data-n="${esc(id)}">${esc(libNotion(id))}</span>`).join('') || '<i>aucune notion dans le chapitre</i>'}</div><a href="#" id="cn-tout" style="font-size:.85rem">tout le programme…</a><div id="cn-tout-z" style="display:none;margin-top:4px"></div></div>`; document.querySelector('.scene').appendChild(z); z.querySelector('.x').onclick = fermerChoix; const brancher = () => z.querySelectorAll('[data-n]').forEach(x => { if (x._ok) return; x._ok = true; x.onclick = () => { fermerChoix(); cb(x.dataset.n); }; }); brancher(); $('cn-tout').onclick = ev => { ev.preventDefault(); ev.target.style.display = 'none'; const z2 = $('cn-tout-z'); z2.style.display = 'block'; z2.innerHTML = DATA.taxo.map(d => d.familles.map(f => { const ns = f.notions.filter(n => !vues[n.id]); return ns.length ? `<details><summary style="cursor:pointer;color:#6a5a48">${esc(d.nom || d.domaine || '')} · ${esc(f.nom || f.famille || '')} (${ns.length})</summary>${ns.map(n => `<span class="fi" data-n="${n.id}">${esc(n.prof || n.eleve || n.id)}</span>`).join('')}</details>` : ''; }).join('')).join(''); brancher(); }; }
function familleDe(id){ return String(id).replace(/-?\d+$/, ''); }
function proposerRemob(){ const E = seance().ecrans; const e = ecran(); const i = S.di; const fam = new Set((e.comp || []).map(familleDe)); const avant = E.slice(0, i).flatMap(z => z.comp || []); const prop = [...new Set(avant.filter(id => fam.has(familleDe(id)) && !(e.comp || []).includes(id) && !(e.remob || []).includes(id)))]; if (!prop.length) { toast('Rien à proposer : aucune notion de la même famille travaillée plus tôt dans le chapitre.'); return; } e.remob = (e.remob || []).concat(prop); marquerModif({ di: i, remob: prop }); toast('Remobilise, proposition par défaut : ' + prop.map(libNotion).join(', ')); tout(); }
function passerEnHeure(h){ const E = seance().ecrans; const e = ecran(); const rf = roleFixe(e); if (rf) return alert(rf + ' ne change pas d\'heure.'); const i = S.di; E.splice(i, 1); let pos; if (h > e.heure) { pos = E.findIndex(z => z.heure === h); if (pos < 0) pos = E.length; if (E[pos] && E[pos].role === 'reactivation') pos++; } else { pos = E.length; for (let q = E.length - 1; q >= 0; q--) { if (E[q].heure === h && E[q].role !== 'fin') { pos = q + 1; break; } } } const anc = e.heure; e.heure = h; E.splice(pos, 0, e); apresTrame({ di: i, passe: e.eid, de: anc, vers: h }); S.di = indexDe(e.eid); toast('Diapo passée en H' + h + ' (elle était en H' + anc + ') — le compte des heures est recalculé.'); tout(); }
function brancherDeclare(da){ const e = ecran(); if (!e) return; const E = seance().ecrans; const sel = da.querySelector('#dc-act'); if (sel) sel.onchange = () => { const v = sel.value; if (v === '+') { const t = prompt('Le titre de la nouvelle activité :'); if (!t) { tout(); return; } const a = nouvelleActivite(t); e.actId = a.id; } else e.actId = v || null; delete e.__num; reindexer(); marquerModif({ di: S.di, activite: e.actId }); tout(); };
  const lie = (id, quoi) => { const el = da.querySelector('#' + id); if (!el) return; el.onblur = () => quoi(el.textContent.trim()); el.onkeydown = ev => { if (ev.key === 'Enter') { ev.preventDefault(); el.blur(); } ev.stopPropagation(); }; };
  lie('dc-atitre', t => { const a = actDe(e); if (a && t && a.titre !== t) { a.titre = t; marquerModif({ di: S.di, titreActivite: t }); tout(); } }); lie('dc-titre', t => { if (t && e.act !== t) { e.act = t; marquerModif({ di: S.di, titre: t }); tout(); } }); lie('dc-leg', t => { const leg = {}; t.split('·').map(x => x.trim()).filter(Boolean).forEach(x => { const m = /^(\S+)\s*=\s*(.+)$/.exec(x); if (m) leg[m[1]] = m[2]; }); if (Object.keys(leg).length) e.legende = leg; else delete e.legende; marquerModif({ di: S.di, legende: leg }); tout(); }); lie('dc-tp', t => { DATA.travailPrevu = DATA.travailPrevu || {}; const k = S.si + '|' + e.heure; if ((DATA.travailPrevu[k] || '') !== t) { if (t) DATA.travailPrevu[k] = t; else delete DATA.travailPrevu[k]; marquerModif({ heure: e.heure, travailPrevu: t }); tout(); } });
  const dur = da.querySelector('#dc-dur'); if (dur) dur.onchange = () => { const v = Math.max(1, +dur.value || 1); if (v !== e.dur) { e.dur = v; if (S.durees && actDe(e)) delete S.durees[actDe(e).id]; marquerModif({ di: S.di, dur: v }); tout(); } };
  const role = da.querySelector('#dc-role'); if (role) role.onchange = () => { const v = role.value || null; if (v === 'bilan' && E.some((z, i) => z.role === 'bilan' && i !== S.di)) { alert('Le bilan est unique : une seule diapo « bilan » par séance.'); tout(); return; } if (v === 'reactivation') { const o = ordreHeure(e.heure).filter(i => !retiree(E[i])); const deja = E.some((z, i) => z.role === 'reactivation' && z.heure === e.heure && i !== S.di); if (deja) { alert('Il y a déjà une réactivation dans cette heure : elle est unique.'); tout(); return; } if (o[0] !== S.di) { alert('La réactivation est la première de son heure : monte d\'abord la diapo en tête de l\'heure.'); tout(); return; } } e.role = v; marquerModif({ di: S.di, role: v }); tout(); };
  da.querySelectorAll('[data-heure]').forEach(b => b.onclick = () => passerEnHeure(+b.dataset.heure)); da.querySelectorAll('[data-retire]').forEach(b => b.onclick = () => { const q = b.dataset.retire; e[q] = (e[q] || []).filter(id => id !== b.dataset.id); marquerModif({ di: S.di, [q]: e[q] }); tout(); }); da.querySelectorAll('[data-plus]').forEach(b => b.onclick = () => choixNotion(id => { const q = b.dataset.plus; e[q] = e[q] || []; if (!e[q].includes(id)) e[q].push(id); marquerModif({ di: S.di, [q]: e[q] }); tout(); })); const pr = da.querySelector('[data-proposer]'); if (pr) pr.onclick = proposerRemob; const na = da.querySelector('[data-nouvelle-act]'); if (na) na.onclick = () => { const t = prompt('Le titre de la nouvelle activité :'); if (!t) return; const a = nouvelleActivite(t); if (!actDe(e) && !e.role) e.actId = a.id; reindexer(); marquerModif({ activite: a.id }); tout(); }; const rn = da.querySelector('[data-renum]'); if (rn) rn.onclick = renumeroter; }
function blocDe(el){""")
