rep("(S.objetsManquants || []).filter(m => m.si === S.si).forEach(m => out.push(","E.forEach((e, i) => { if (!e.role && !actDe(e)) out.push({ di: i, k: 'activite', l: `Diapo « ${e.act} » sans numéro d'activité`, ou: `diapo ${i + 1}`, faire: 'rattache-la à une activité (la carte « Ce que la diapo déclare ») — un chapitre dont les activités ne sont pas toutes numérotées est refusé à l\\'import (3.2 bis)', copier: `Diapo « ${e.act} » (chapitre « ${seance().titre} ») : à rattacher à une activité numérotée (numéro continu sur le chapitre).` }); }); (S.objetsManquants || []).filter(m => m.si === S.si).forEach(m => out.push(")
